.reactable .rt-thead{border-bottom:1px solid #333}
.reactable .rt-tr,.reactable .rt-td,.reactable .rt-th{border-left:0!important;border-right:0!important;background:#fff}
.reactable .rt-tbody .rt-tr-group{border-bottom:0}
